use kimo_core::commands::{dispatch,Session};use serde_json::json;
#[test]fn legacy_audio_hashes_unchanged(){let dir=std::env::temp_dir().join("kimo-audio-compat");std::fs::create_dir_all(&dir).unwrap();let music=dir.join("music.wav");let speech=dir.join("speech.wav");let mk=|path:&std::path::Path,speech:bool|{let pcm:Vec<f32>=(0..96000).flat_map(|i|{let v=if speech&&!(24000..48000).contains(&i){0.}else{((i as f64/48000.)*std::f64::consts::TAU*if speech{330.}else{220.}).sin()as f32*0.15};[v,v]}).collect();kimo_core::audio::write_wav(path.to_str().unwrap(),&pcm).unwrap();};mk(&music,false);mk(&speech,true);let mut s=Session::new();let mut tracks=vec![];for path in [&music,&speech]{let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let r=dispatch(&mut s,"add_audio_clip",&json!({"asset_id":a,"start":0,"duration":2})).unwrap();tracks.push(r["track_id"].clone());}
for mode in ["plain","auto_duck"]{if mode=="auto_duck"{dispatch(&mut s,"auto_duck",&json!({"track":tracks[0],"under":tracks[1],"amount_db":-18})).unwrap();}let path=dir.join("export.wav");dispatch(&mut s,"export_audio",&json!({"path":path})).unwrap();let hash=kimo_core::deps::sha256_hex(&std::fs::read(path).unwrap());let pcm=kimo_core::audio::mix_strict(&s.project).unwrap();let bytes:Vec<_>=pcm.iter().flat_map(|v|v.to_le_bytes()).collect();let strict=kimo_core::deps::sha256_hex(&bytes);let(expected_wav,expected_pcm)=if mode=="plain"{("030e131c894da079589efbd8dbd3ea0268b5feab9352bf00c7be19f3ab974507","09d340b20211c8a515b7257e4795aa32b5bdf907c1989aa2d683899523f4c3c3")}else{("18339914e6ef610cea9d8772c38d0307a06285dad15a092b7270ab989828415a","75661646bc399d96005fcd53c48f0f606faa44d47319946b7e5a48112e81f590")};assert_eq!(hash,expected_wav);assert_eq!(strict,expected_pcm);}}
